import { useEffect, useState } from "react"
import { QueryClient, QueryClientProvider, useMutation, useQueries, useQuery } from "@tanstack/react-query"
import { NavLink, Route, Routes, useParams, useSearchParams } from "react-router-dom"
import { getArchiveValidation, getAsset, getAssetFundamental, getAssetHistory, getAssetIndicators, getAssetLevels, getAssetNewsDataset, getEvents, getHealth, getOverview, getReviews, getReviewSummary, getValidationDepth, getValidationPolicy, getValidationReport, getGitHubWatch, pollGitHubWatch, updateReview, type ArchiveValidationReport, type AssetDetail, type AssetMetric, type EventRecord, type ForwardOutcome, type FundamentalSnapshot, type GitHubWatch, type ReviewItem, type ReviewStatus, type Signal, type ValidationDepthReport, type ValidationPolicyReport, type ValidationReport } from "./lib/api"
import "./styles.css"

const client = new QueryClient({ defaultOptions: { queries: { retry: false } } })
const ASSETS = ["BTC", "ETH", "SOL", "HYPE", "ZEC"]

export default function App() { return <QueryClientProvider client={client}><Shell /></QueryClientProvider> }

function Shell() {
  const [menu, setMenu] = useState(false)
  return <div className="signal-room"><aside className="room-nav"><NavLink to="/" className="room-brand"><span className="brand-orbit">◈</span><span>Signal Room<small>CRYPTO RADAR</small></span></NavLink><div className="nav-kicker">Workspace</div><nav aria-label="Основная навигация"><Nav to="/" label="Обзор" icon="⌂" /><Nav to="/signals" label="Сигналы" icon="↗" /><Nav to="/reviews" label="Validation" icon="◌" /><Nav to="/events" label="Журнал" icon="≋" /><Nav to="/health" label="Система" icon="◉" /><Nav to="/github" label="GitHub Watch" icon="⌁" /></nav><div className="nav-footer"><span className="status-led" /> Execution disabled <small>analyst review enabled · evidence preserved</small></div></aside><header className="room-mobile"><NavLink to="/" className="room-brand"><span className="brand-orbit">◈</span><span>Signal Room</span></NavLink><button aria-label="Меню" aria-expanded={menu} onClick={() => setMenu(!menu)}>☰</button></header>{menu && <nav className="mobile-menu" aria-label="Мобильная навигация">{[["/","Обзор"],["/signals","Сигналы"],["/reviews","Validation"],["/events","Журнал"],["/health","Система"],["/github","GitHub Watch"]].map(([to,label]) => <NavLink key={to} to={to} onClick={() => setMenu(false)}>{label}</NavLink>)}</nav>}<div className="room-content"><Routes><Route path="/" element={<Overview />} /><Route path="/signals" element={<Signals />} /><Route path="/reviews" element={<Reviews />} /><Route path="/events" element={<Events />} /><Route path="/health" element={<Health />} /><Route path="/github" element={<GitHub />} /><Route path="/asset/:asset" element={<Asset />} /></Routes></div></div>
}
function Nav({ to, label, icon }: { to: string; label: string; icon: string }) { return <NavLink to={to} end={to === "/"} className="room-nav-item"><i>{icon}</i><span>{label}</span></NavLink> }
function Frame({ eyebrow, title, description, children }: { eyebrow: string; title: string; description: string; children: React.ReactNode }) { return <main className="room-page"><header className="room-header"><div><span className="kicker">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div><div className="live-chip"><span className="status-led" /> LIVE<br /><small>execution disabled · review enabled</small></div></header>{children}</main> }
function Loading() { return <div className="room-state"><span className="spinner" /> Синхронизация evidence…</div> }
function Failure({ label = "Данные" }: { label?: string }) { return <div className="room-state room-error"><strong>{label} недоступны</strong><span>Состояние сохранено. Повтори запрос позже.</span></div> }
function Empty({ children }: { children: React.ReactNode }) { return <div className="room-empty">{children}</div> }

function Overview() {
  const q = useQuery({ queryKey: ["overview", ASSETS], queryFn: () => getOverview(ASSETS), refetchInterval: 60000 })
  if (q.isPending) return <Loading />; if (q.isError) return <Failure />
  const high = [...q.data.signals].sort((a,b) => severityRank(b.severity) - severityRank(a.severity) || b.confidence-a.confidence)[0]
  return <Frame eyebrow="MARKET CONTROL / 01" title="Обзор рынка" description="Главный вывод, доказательства и состояние наблюдаемого universe — в одном экране."><section className="control-hero"><div><span className="kicker">Market posture</span><strong>{high?.market_direction ?? "нет данных"}</strong><p>{high?.fact ?? "Composite-сигналы ещё не сформированы."}</p><div className="hero-meta"><span>confidence {high ? Math.round(high.confidence*100) : "—"}%</span><span>{high ? severityLabel(high.severity) : "нет риска"}</span><span>{q.data.signals.length} signals</span></div></div><div className="hero-score"><span>PRIMARY SIGNAL</span><b>{high?.asset ?? "—"}</b><small>{high?.requires_manual_review ? "manual review required" : "observation"}</small><NavLink to={high ? `/asset/${high.asset}?from=overview&asset=${high.asset}` : "/signals"}>Открыть evidence →</NavLink></div></section><div className="metric-row"><Metric label="Assets" value={String(q.data.assets.length)} detail="tracked" /><Metric label="Signals" value={String(q.data.signals.length)} detail="current snapshot" /><Metric label="Review" value={String(q.data.signals.filter(s=>s.requires_manual_review).length)} detail="human-in-loop" /><Metric label="Mode" value="READ" detail="auto-trade false" /></div><SignalsPanel signals={q.data.signals.slice(0,4)} title="Сигналы, требующие внимания" navigationContext="overview" /><MarketGrid assets={q.data.assets} signals={q.data.signals} /></Frame>
}
function Signals() { const q = useQuery({ queryKey:["overview",ASSETS],queryFn:()=>getOverview(ASSETS),refetchInterval:60000 }); const technical = useQueries({ queries: ASSETS.map(asset => ({ queryKey:["indicators",asset], queryFn:()=>getAssetIndicators(asset), refetchInterval:60000 })) }); if(q.isPending)return <Loading/>;if(q.isError)return <Failure/>; const technicalSignals = technical.flatMap(item => item.data?.signals ?? []); return <Frame eyebrow="EVIDENCE / 02" title="Сигналы" description="Composite posture first; DeMark, TD Sequential and volume evidence are shown as a separate technical layer."><div className="section-bar"><span>{q.data.signals.length} composite observations</span><span>{technicalSignals.length} technical observations</span></div><SignalsPanel signals={[...q.data.signals].sort((a,b)=>severityRank(b.severity)-severityRank(a.severity))} title="Composite signal feed" navigationContext /><TechnicalSignalsPanel signals={technicalSignals} loading={technical.some(item => item.isPending)} error={technical.some(item => item.isError)} /></Frame> }
function TechnicalSignalsPanel({ signals, loading = false, error = false }: { signals: Signal[]; loading?: boolean; error?: boolean }) { const [params, setParams] = useSearchParams(); if (loading) return <section className="room-section"><Empty>DeMark / TD Sequential synchronizing…</Empty></section>; if (error) return <section className="room-section"><Empty>DeMark / TD Sequential недоступны.</Empty></section>; const asset = params.get("asset") || "all"; const timeframe = params.get("timeframe") || "all"; const assets = Array.from(new Set(signals.map(signal => signal.asset))).sort(); const timeframes = ["1m", "10m", "1h", "6h", "1d", "1w"]; const updateFilter = (key: "asset" | "timeframe", value: string) => { const next = new URLSearchParams(params); if (value === "all") next.delete(key); else next.set(key, value); setParams(next); }; const filtered = signals.filter(signal => (asset === "all" || signal.asset === asset) && (timeframe === "all" || String(signal.measurements.timeframe ?? "") === timeframe)); const evidenceQuery = (signal: Signal) => { const next = new URLSearchParams(); next.set("from", "signals"); next.set("asset", signal.asset); if (signal.measurements.timeframe) next.set("timeframe", String(signal.measurements.timeframe)); return `/asset/${signal.asset}?${next.toString()}`; }; return <section className="room-section"><div className="section-title"><h2>DeMark / TD Sequential</h2><span>{filtered.length} / {signals.length} technical observations</span></div><div className="technical-filters"><div className="filter-pills" role="group" aria-label="Фильтр активов"><span>Asset</span><button className={asset === "all" ? "active" : ""} onClick={() => updateFilter("asset", "all")}>Все</button>{assets.map(value => <button className={asset === value ? "active" : ""} key={value} onClick={() => updateFilter("asset", value)}>{value}</button>)}</div><div className="filter-pills" role="group" aria-label="Фильтр таймфрейма"><span>Timeframe</span><button className={timeframe === "all" ? "active" : ""} onClick={() => updateFilter("timeframe", "all")}>Все</button>{timeframes.map(value => <button className={timeframe === value ? "active" : ""} key={value} onClick={() => updateFilter("timeframe", value)}>{value}</button>)}</div></div>{filtered.length ? <div className="technical-feed">{filtered.map(signal => { const m=signal.measurements; const td=typeof m.td_sequential === "object" && m.td_sequential ? m.td_sequential as Record<string,unknown> : {}; const setup=Number(td.buy_setup_count ?? 0)>0 ? `Buy ${td.buy_setup_count}/9` : Number(td.sell_setup_count ?? 0)>0 ? `Sell ${td.sell_setup_count}/9` : "нет setup"; const countdown=Number(td.buy_countdown ?? 0)>0 ? `Buy ${td.buy_countdown}/13` : Number(td.sell_countdown ?? 0)>0 ? `Sell ${td.sell_countdown}/13` : "нет countdown"; return <article className="technical-row" key={signal.signal_id}><div><b>{signal.asset}</b><span>{String(m.timeframe ?? "—")}</span></div><strong>{String(m.demark_direction ?? signal.market_direction)}</strong><div><span>DeMarker</span><b>{typeof m.demark === "number" ? m.demark.toFixed(3) : "нет данных"}</b></div><div><span>TD</span><b>{String(td.signal_state ?? "нет данных")}</b><small>{setup} · {countdown}</small></div><div><span>Volume</span><b>{typeof m.volume_ratio === "number" ? `${m.volume_ratio.toFixed(2)}×` : "нет данных"}</b><small>{String(m.volume_regime ?? "режим не определён")}</small></div><NavLink to={evidenceQuery(signal)}>evidence ↗</NavLink></article> })}</div> : <Empty>Нет технических сигналов для выбранного фильтра.</Empty>}</section> }

function SignalsPanel({ signals, title, navigationContext = false, navigationTimeframe }: { signals: Signal[]; title: string; navigationContext?: boolean | "overview" | "signals"; navigationTimeframe?: string | null }) { return <section className="room-section"><div className="section-title"><h2>{title}</h2><span>fact → basis → review</span></div>{signals.length ? <div className="signal-feed">{signals.map(s=><SignalCard key={s.signal_id} signal={s} navigationContext={navigationContext} navigationTimeframe={navigationTimeframe}/>)}</div> : <Empty>Сигналов пока нет.</Empty>}</section> }
function SignalCard({ signal, navigationContext = false, navigationTimeframe }: { signal: Signal; navigationContext?: boolean | "overview" | "signals"; navigationTimeframe?: string | null }) { const drivers = Array.isArray(signal.measurements.drivers) ? signal.measurements.drivers as Array<{ fact?: string }> : []; const source = navigationContext === "overview" ? "overview" : navigationContext ? "signals" : null; const evidenceQuery = new URLSearchParams(); if (source) { evidenceQuery.set("from", source); evidenceQuery.set("asset", signal.asset); const timeframe = navigationTimeframe ?? (signal.measurements.timeframe ? String(signal.measurements.timeframe) : null); if (source === "signals" && timeframe) evidenceQuery.set("timeframe", timeframe); } const evidencePath = `/asset/${signal.asset}${evidenceQuery.toString() ? `?${evidenceQuery.toString()}` : ""}`; return <article className={`signal-card tone-${signal.severity}`} key={signal.signal_id}><div className="signal-index">{String(signal.asset).padStart(3,"0")}<span>{signalTypeLabel(signal.signal_type)}</span></div><div className="signal-body"><div className="signal-line"><strong>{signal.market_direction}</strong><Severity severity={signal.severity}/></div><p className="signal-fact">{signal.fact}</p>{drivers[0]?.fact && <p className="signal-driver"><b>DRIVER</b> {drivers[0].fact}</p>}<details><summary>Показать основание и источники</summary><p>{signal.basis}</p><div className="inline-meta"><span>confidence {Math.round(signal.confidence*100)}%</span><span>{signal.evidence_metadata.source_count} sources</span><span>{signal.requires_manual_review ? "manual review" : "observe"}</span></div>{signal.source_urls.length>0&&<div className="source-list">{signal.source_urls.map(url=><span key={url}>{safeHost(url)}</span>)}</div>}</details></div><NavLink className="signal-open" to={evidencePath}>Analyze ↗</NavLink></article> }
function MarketGrid({ assets, signals }: { assets: AssetMetric[]; signals: Signal[] }) { return <section className="room-section"><div className="section-title"><h2>Market universe</h2><span>Hyperliquid snapshot</span></div><div className="market-grid">{assets.map(a=>{const s=signals.find(x=>x.asset===a.asset&&x.signal_type==="composite_market_risk");return <NavLink className="market-tile" to={`/asset/${a.asset}?from=overview&asset=${a.asset}`} key={a.asset}><div><b>{a.asset}</b><Severity severity={s?.severity??"low"}/></div><strong>{formatPrice(a.mark_price)}</strong><span>{s?.market_direction??"нет сигнала"}</span><dl><div><dt>funding</dt><dd>{formatPercent(a.funding_rate*100)}</dd></div><div><dt>OI</dt><dd>{formatCompact(a.open_interest)}</dd></div></dl></NavLink>})}</div></section> }
function Asset() {
  const { asset = "" } = useParams()
  const [params] = useSearchParams()
  const normalized = asset.trim().toUpperCase()
  const enabled = Boolean(normalized)
  const from = params.get("from")
  const fromSignals = from === "signals"
  const fromOverview = from === "overview"
  const returnAsset = params.get("asset") || normalized
  const returnTimeframe = params.get("timeframe")
  const focusedTimeframe = fromSignals ? returnTimeframe : null
  const returnQuery = new URLSearchParams()
  if (returnAsset) returnQuery.set("asset", returnAsset)
  if (returnTimeframe) returnQuery.set("timeframe", returnTimeframe)
  const returnPath = fromOverview ? "/" : "/signals"
  const returnToSource = `${returnPath}${returnPath === "/signals" && returnQuery.toString() ? `?${returnQuery.toString()}` : ""}`
  const q = useQuery({ queryKey: ["asset", normalized], queryFn: () => getAsset(normalized), enabled })
  const fundamental = useQuery({ queryKey: ["fundamental", normalized], queryFn: () => getAssetFundamental(normalized, 20), enabled })
  const news = useQuery({ queryKey: ["dataset", normalized], queryFn: () => getAssetNewsDataset(normalized, 30), enabled })
  const indicators = useQuery({ queryKey: ["indicators", normalized], queryFn: () => getAssetIndicators(normalized), enabled, refetchInterval: 60_000 })
  const levels = useQuery({ queryKey: ["levels", normalized], queryFn: () => getAssetLevels(normalized), enabled })
  const history = useQuery({ queryKey: ["history", normalized], queryFn: () => getAssetHistory(normalized, "mark_price", 30), enabled })
  if (q.isPending) return <Loading />
  if (q.isError) return <Failure label="Актив" />
  const d = q.data
  const signal = d.signals.find(x => x.signal_type === "composite_market_risk")
  const consensus = indicators.data?.aggregate
  return <Frame eyebrow={`ASSET WORKSPACE / ${d.asset.asset}`} title={d.asset.asset} description="Decision surface: current posture first, evidence and raw market facts second.">
    {(fromSignals || fromOverview) && <div className="context-bar"><span>{fromOverview ? "Market overview context" : `Signal context · ${returnTimeframe ?? "all timeframes"}`}</span><NavLink to={returnToSource}>{fromOverview ? "← Вернуться к обзору" : "← Вернуться к сигналам"}</NavLink></div>}
    <section className="asset-command"><div><span className="kicker">Current posture</span><strong>{signal?.market_direction ?? "нет данных"}</strong><p>{signal?.fact ?? "Composite-сигнал не сформирован."}</p></div><div className="asset-command-stats"><Metric label="Mark" value={formatPrice(d.asset.mark_price)} detail="USD"/><Metric label="Confidence" value={signal ? `${Math.round(signal.confidence * 100)}%` : "—"} detail="signal"/><Metric label="Review" value={signal?.requires_manual_review ? "YES" : "NO"} detail="human-in-loop"/></div></section>
    <SignalsPanel signals={d.signals} title="Asset evidence" navigationContext={fromOverview ? "overview" : fromSignals ? "signals" : false} navigationTimeframe={returnTimeframe} />
    <ConsensusPanel aggregate={consensus} loading={indicators.isPending} error={indicators.isError} />
    <TechnicalIndicatorsPanel signals={indicators.data?.signals} generatedAt={indicators.data?.generated_at} focusedTimeframe={focusedTimeframe} loading={indicators.isPending} error={indicators.isError} />
    <section className="room-section"><div className="section-title"><h2>Market facts</h2><span>{d.asset.asset} · current snapshot</span></div><div className="fact-grid"><Fact label="Mark price" value={formatPrice(d.asset.mark_price)}/><Fact label="Mid price" value={d.asset.mid_price == null ? "нет данных" : formatPrice(d.asset.mid_price)}/><Fact label="Funding" value={formatPercent(d.asset.funding_rate * 100)}/><Fact label="Open interest" value={formatCompact(d.asset.open_interest)}/><Fact label="24h notional" value={formatCompact(d.asset.day_notional_volume)}/></div></section>
    <LevelsPanel levels={levels.data?.levels} loading={levels.isPending} error={levels.isError} />
    <HistoryPanel points={history.data?.metrics.mark_price} loading={history.isPending} error={history.isError} />
    <FundamentalPanel snapshot={fundamental.data} loading={fundamental.isPending} error={fundamental.isError} />
    <Dataset dataset={news.data} loading={news.isPending} error={news.isError}/>
  </Frame>
}

function ConsensusPanel({ aggregate, loading, error }: { aggregate?: Awaited<ReturnType<typeof getAssetIndicators>>["aggregate"]; loading: boolean; error: boolean }) {
  if (loading) return <section className="room-section"><Empty>Consensus synchronizing…</Empty></section>
  if (error || !aggregate) return <section className="room-section"><Empty>Индикаторный consensus недоступен.</Empty></section>
  const horizons = aggregate.horizons ? Object.entries(aggregate.horizons) as Array<[string, { direction: string; timeframes: string[]; status: string }]> : []
  return <section className="room-section"><div className="section-title"><h2>Multi-timeframe consensus</h2><span>{aggregate.quality_label ?? "качество не оценено"} · data quality {aggregate.data_quality ?? "—"}</span></div><div className="consensus-panel"><div className="consensus-lead"><span className="kicker">Consensus verdict</span><strong>{consensusVerdict(aggregate)}</strong><p>{aggregate.basis}</p><div className="inline-meta"><span>weighted direction: {aggregate.market_direction}</span><span>score {aggregate.direction_score ?? "—"}</span><span>{aggregate.direction_agreement ? "agreement" : "conflict / partial"}</span><span>confirmed {aggregate.confirmed_timeframes.length || "нет"}</span></div></div><div className="horizon-grid">{horizons.length ? horizons.map(([name, item]) => <div className="horizon-card" key={name}><span>{name}</span><strong>{item.direction}</strong><small>{item.status}</small><em>{item.timeframes.join(" · ") || "нет таймфреймов"}</em></div>) : <Empty>Горизонты не рассчитаны.</Empty>}</div></div></section>
}

function consensusVerdict(aggregate: Awaited<ReturnType<typeof getAssetIndicators>>["aggregate"]) {
  if (aggregate.direction_agreement && aggregate.confirmed_timeframes.length > 0) return aggregate.market_direction
  const horizonDirections = aggregate.horizons ? Object.values(aggregate.horizons).map(horizon => horizon.direction).filter(direction => direction !== "нейтральное") : []
  return horizonDirections.length > 0 && new Set(horizonDirections).size === 1 ? "частичное подтверждение" : "нет единого направления"
}
function TechnicalIndicatorsPanel({ signals, generatedAt, focusedTimeframe, loading, error }: { signals?: Signal[]; generatedAt?: string; focusedTimeframe?: string | null; loading: boolean; error: boolean }) {
  const [now, setNow] = useState(() => Date.now())
  useEffect(() => { const timer = window.setInterval(() => setNow(Date.now()), 60_000); return () => window.clearInterval(timer) }, [])
  if (loading) return <section className="room-section"><Empty>DeMark / TD Sequential synchronizing…</Empty></section>
  if (error || !signals?.length) return <section className="room-section"><Empty>DeMark / TD Sequential недоступны.</Empty></section>
  const orderedSignals = focusedTimeframe ? [...signals].sort((a, b) => Number(String(b.measurements.timeframe) === focusedTimeframe) - Number(String(a.measurements.timeframe) === focusedTimeframe)) : signals
  return <section className="room-section"><div className="section-title"><h2>Основные индикаторы</h2><span>{focusedTimeframe ? `focused · ${focusedTimeframe}` : "DeMark · TD Sequential · закрытые свечи"}</span><small aria-label="Последнее обновление индикаторов">обновлено <b>{generatedAt ? formatDate(generatedAt) : "нет данных"}</b>{generatedAt && <><span> · </span><b className={indicatorSnapshotStatus(new Date(generatedAt).getTime(), now) === "stale" ? "stale" : "fresh"}>{indicatorSnapshotStatus(new Date(generatedAt).getTime(), now) === "stale" ? "данные устарели" : "актуально"}</b><span> · {indicatorSnapshotAgeLabel(new Date(generatedAt).getTime(), now)}</span></>}</small></div><div className="indicator-grid">{orderedSignals.map(signal => { const m = signal.measurements; const td = typeof m.td_sequential === "object" && m.td_sequential ? m.td_sequential as Record<string, unknown> : {}; const structure = typeof m.td_structure === "object" && m.td_structure ? m.td_structure as Record<string, unknown> : {}; const retracement = typeof m.td_retracement === "object" && m.td_retracement ? m.td_retracement as Record<string, unknown> : {}; const scenario = typeof m.td_scenario === "object" && m.td_scenario ? m.td_scenario as Record<string, unknown> : {}; const direction = String(m.demark_direction ?? signal.market_direction); const setup = Number(td.buy_setup_count ?? 0) > 0 ? `Buy ${td.buy_setup_count}/9` : Number(td.sell_setup_count ?? 0) > 0 ? `Sell ${td.sell_setup_count}/9` : "нет setup"; const countdown = Number(td.buy_countdown ?? 0) > 0 ? `Buy ${td.buy_countdown}/13` : Number(td.sell_countdown ?? 0) > 0 ? `Sell ${td.sell_countdown}/13` : "нет countdown"; const intersection = td.buy_intersection_confirmed === true ? "Buy подтверждён" : td.sell_intersection_confirmed === true ? "Sell подтверждён" : "не подтверждён"; const entry = td.entry_signal ? String(td.entry_signal) : "нет entry"; const stop = td.buy_stop_loss_true_range ?? td.sell_stop_loss_true_range; const actualEntry = td.buy_entry_price ?? td.sell_entry_price; const price = (value: unknown) => typeof value === "number" ? formatPrice(value) : "нет данных"; const focused = focusedTimeframe === String(m.timeframe); return <article className={`indicator-card${focused ? " focused" : ""}`} key={signal.signal_id}>{focused && <span className="indicator-focus">SELECTED FROM SIGNALS</span>}<div className="indicator-card-head"><b>{String(m.timeframe ?? "—")}</b><span className={direction === "нейтральное" ? "neutral" : "directional"}>{direction}</span></div><div className="indicator-values"><div><span>DeMarker</span><strong>{typeof m.demark === "number" ? m.demark.toFixed(3) : "нет данных"}</strong><small>{String(m.demark_zone ?? "зона не определена")}</small></div><div><span>TD Sequential</span><strong>{String(td.signal_state ?? "нет данных")}</strong><small>{setup} · {countdown}</small></div><div><span>Volume</span><strong>{typeof m.volume_ratio === "number" ? `${m.volume_ratio.toFixed(2)}×` : "нет данных"}</strong><small>{String(m.volume_regime ?? "режим не определён")}</small></div></div><details className="indicator-details"><summary>Показать TD / REI evidence</summary><div className="indicator-detail-grid"><span>REI <b>{typeof m.rei === "number" ? m.rei.toFixed(1) : "нет данных"}</b> · {String(m.rei_regime ?? "режим не определён")}</span><span>Exhaustion <b>{String(m.demark_exhaustion ?? "нет данных")}</b></span><span>TD Lines <b>{price(structure.td_demand_line)} demand · {price(structure.td_supply_line)} supply</b></span><span>Breakout <b>{structure.demand_breakout === "true" || structure.demand_breakout === true ? "demand" : structure.supply_breakout === "true" || structure.supply_breakout === true ? "supply" : "нет"}</b></span><span>Retracement <b>{String(retracement.retracement_zone ?? "нет данных")}</b> · 38.2% {price(retracement.retracement_382)} · 61.8% {price(retracement.retracement_618)}</span><span aria-label="Фактический вход">Intersection <b>{intersection}</b> · entry <b>{entry}</b> · Фактический вход <b>{typeof actualEntry === "number" ? price(actualEntry) : "не рассчитан"}</b> · stop TR <b>{typeof stop === "number" ? price(stop) : "не рассчитан"}</b></span><span aria-label="Источник баров">Источник баров <b>{Number(m.closed_candle_count ?? 0)}</b> закрытых OHLCV-свечей</span><span aria-label="Последний закрытый бар">Последний закрытый бар <b>{typeof m.candle_open_time === "number" ? formatCandleOpenTime(m.candle_open_time) : "нет данных"}</b></span><span aria-label="Закрытие последнего бара">Закрытие последнего бара <b>{typeof m.candle_open_time === "number" ? formatCandleOpenTime(m.candle_open_time + candleIntervalMs(String(m.timeframe ?? ""))) : "нет данных"}</b></span><span aria-label="Следующее ожидаемое закрытие">Следующее ожидаемое закрытие <b>{typeof m.candle_open_time === "number" ? formatCandleOpenTime(m.candle_open_time + 2 * candleIntervalMs(String(m.timeframe ?? ""))) : "нет данных"}</b></span>{typeof m.candle_open_time === "number" ? <CandleFreshness candleOpenTime={m.candle_open_time} timeframe={String(m.timeframe ?? "")} /> : <span aria-label="Свежесть баров">Свежесть баров <b>нет данных</b></span>}<span>Scenario <b>{String(scenario.scenario ?? "нет данных")}</b> · {String(scenario.reason ?? "нет причины")}</span></div></details></article>})}</div></section>
}
function LevelsPanel({ levels, loading, error }: { levels?: Awaited<ReturnType<typeof getAssetLevels>>["levels"]; loading: boolean; error: boolean }) {
  if (loading) return <section className="room-section"><Empty>Levels synchronizing…</Empty></section>
  if (error || !levels) return <section className="room-section"><Empty>Уровни поддержки и сопротивления недоступны.</Empty></section>
  return <section className="room-section"><div className="section-title"><h2>Support / resistance</h2><span>period · strength · range</span></div>{levels.length ? <div className="levels-grid">{levels.map(level => <article className="level-card" key={`${level.period}-${level.start}`}><div><b>{level.period}</b><Severity severity={level.strength === "strong" ? "high" : level.strength === "medium" ? "medium" : "low"}/></div><strong>{formatPrice(level.support)} — {formatPrice(level.resistance)}</strong><small>{level.start} → {level.end}</small></article>)}</div> : <Empty>Уровни пока не рассчитаны.</Empty>}</section>
}

function HistoryPanel({ points, loading, error }: { points?: Array<{ observed_at: number; value: number }>; loading: boolean; error: boolean }) {
  if (loading) return <section className="room-section"><Empty>History synchronizing…</Empty></section>
  if (error || !points) return <section className="room-section"><Empty>История mark price недоступна.</Empty></section>
  const latest = points.at(-1)
  const first = points[0]
  const values = points.map(point => point.value)
  const min = Math.min(...values)
  const max = Math.max(...values)
  const span = Math.max(1, max - min)
  const delta = latest && first && first.value !== 0 ? ((latest.value - first.value) / first.value) * 100 : null
  const bars = points.slice(-30).map(point => Math.max(8, Math.min(100, ((point.value - min) / span) * 92 + 8)))
  return <section className="room-section"><div className="section-title"><h2>Price history</h2><span>{points.length} observations · {latest ? formatDate(latest.observed_at) : "нет данных"}</span></div><div className="history-panel"><div><span className="kicker">30-point window</span><strong>{latest ? formatPrice(latest.value) : "нет данных"}</strong><p>{delta == null ? "Изменение окна не вычисляется." : `Изменение окна: ${formatOutcome(delta)}`}</p></div><div className="history-bars" aria-label="Mark price history">{bars.map((height, index) => <i key={`${index}-${height}`} style={{ height: `${height}%` }} />)}</div></div></section>
}
function FundamentalPanel({ snapshot, loading, error }: { snapshot?: FundamentalSnapshot; loading: boolean; error: boolean }) {
  if (loading) return <section className="room-section"><Empty>Fundamental evidence synchronizing…</Empty></section>
  if (error || !snapshot) return <section className="room-section"><Empty>Fundamental evidence unavailable.</Empty></section>
  const synthesisCopy = snapshot.synthesis.status === "insufficient" ? "Недостаточно направленной evidence." : snapshot.synthesis.status === "conflicting" ? "Источники расходятся — требуется analyst review." : snapshot.synthesis.status === "emerging" ? "Ранний направленный сигнал; выборка мала." : "Evidence достаточно для наблюдаемого summary."
  return <section className="room-section fundamental-panel"><div className="section-title"><div><h2>Fundamental evidence</h2><span className="panel-subtitle">News + GitHub · source dates preserved</span></div><span className="read-only-badge">READ-ONLY</span></div><div className={`fundamental-synthesis status-${snapshot.synthesis.status}`}><div><span className="kicker">Synthesis</span><strong>{snapshot.synthesis.status}</strong><p>{snapshot.synthesis.direction} · {snapshot.synthesis.positive_count} positive / {snapshot.synthesis.negative_count} negative</p></div><small>{synthesisCopy}</small></div><div className="fundamental-grid"><div className="fundamental-column"><div className="section-title"><h3>News</h3><span>{snapshot.news.count} items · {snapshot.news.status}</span></div>{snapshot.news.items.length ? snapshot.news.items.slice(0, 5).map(item => <article className="evidence-row" key={item.article_id}><div className="evidence-row-main"><a href={item.url} target="_blank" rel="noreferrer">{item.title}</a><span>{item.event_type} · {item.score.label}</span></div><time dateTime={item.published_at} title={item.published_at}>{formatEvidenceDate(item.published_at)}</time></article>) : <Empty>News evidence отсутствует.</Empty>}</div><div className="fundamental-column"><div className="section-title"><h3>GitHub</h3><span>{snapshot.github.events.length} events · {snapshot.github.status}</span></div><small className="mapping-line">{snapshot.github.mapped_repos.join(" · ") || "repository mapping отсутствует"}</small>{snapshot.github.events.length ? snapshot.github.events.slice(0, 5).map(event => <article className="evidence-row" key={event.external_id}><div className="evidence-row-main"><a href={event.url} target="_blank" rel="noreferrer">{event.title}</a><span>{event.repo} · {event.kind}</span></div><time dateTime={event.occurred_at} title={event.occurred_at}>{formatEvidenceDate(event.occurred_at)}</time></article>) : <Empty>{snapshot.github.status === "unmapped" ? "GitHub mapping отсутствует." : "GitHub events отсутствуют."}</Empty>}</div></div><p className="panel-note">{snapshot.note}</p></section>
}

function Dataset({ dataset, loading, error }: { dataset?: Awaited<ReturnType<typeof getAssetNewsDataset>>; loading: boolean; error: boolean }) {
  if (loading) return <section className="room-section"><Empty>Dataset synchronizing…</Empty></section>
  if (error || !dataset) return <section className="room-section"><Empty>Dataset unavailable.</Empty></section>
  const scores = dataset.records.map(r => r.production_score)
  const horizons = ["1h", "6h", "1d", "1w"] as const
  const eventTypes = Object.entries(dataset.event_type_breakdown ?? {}).sort((a,b) => b[1].count - a[1].count)
  return <section className="room-section"><div className="section-title"><h2>News dataset readiness</h2><span>read-only · {dataset.training_readiness.min_samples} samples minimum</span></div><div className="dataset-strip"><b>{scores.length} records</b><span>score {scores.length ? `${scores[0] > 0 ? "+" : ""}${scores[0]}` : "—"}</span><span>positive {scores.filter(x => x > 0).length}</span><span>neutral {scores.filter(x => x === 0).length}</span><span>negative {scores.filter(x => x < 0).length}</span><span>labels: unavailable</span></div><div className="dataset-readiness" aria-label="News dataset horizon readiness">{horizons.map(horizon => { const readiness = dataset.readiness[horizon]; const training = dataset.training_readiness.horizons[horizon]; return <article className="readiness-card" key={horizon}><div><b>{horizon}</b><span className={`readiness-state ${readinessStatus(readiness)}`}>{readinessStatusLabel(readiness)}</span></div><strong>{formatPercent(readiness.coverage_pct)} coverage</strong><small>{readiness.ready_count} ready · {readiness.pending_count} pending · {readiness.data_gap_count} data gap</small><em>{training.status === "ready" ? "training ready" : `training blocked · ${training.reasons.join(", ") || "needs more evidence"}`}</em></article> })}</div><div className="dataset-taxonomy"><div className="section-title"><h3>Event taxonomy breakdown</h3><span>collection evidence · not composite</span></div>{eventTypes.map(([eventType, bucket]) => { const oneHour = bucket.by_horizon["1h"]; const scores = bucket.score_distribution; return <article className="taxonomy-row" key={eventType}><div><b>{eventType.replaceAll("_", " ")}</b><small>{bucket.count} records · {bucket.sample_status === "insufficient_sample" ? "insufficient sample" : bucket.sample_status === "collecting" ? "collecting" : "sufficient for review"} · 1h {oneHour.quality_status === "insufficient_sample" ? "insufficient outcome sample" : oneHour.quality_status === "collecting" ? "outcome collection" : "review candidate"}</small></div><span>{oneHour.ready_count} ready · {oneHour.pending_count} pending · {oneHour.data_gap_count} data gap</span><small className="taxonomy-horizons">{horizons.map(horizon => { const item = bucket.by_horizon[horizon]; return <span key={horizon} data-quality-status={item.quality_status} aria-label={`${horizon} taxonomy readiness`}>{horizon}: {item.ready_count} ready · {item.pending_count} pending · {item.data_gap_count} gap · {qualityStatusLabel(item.quality_status)}</span> })}</small><strong>{oneHour.quality_status === "insufficient_sample" ? "quality metrics withheld" : oneHour.average_return_pct == null ? "return: нет данных" : `1h ${formatOutcome(oneHour.average_return_pct)} · +${oneHour.positive_rate_pct}% / −${oneHour.negative_rate_pct}% · dir ${oneHour.directional_accuracy_pct ?? "нет данных"}% (n=${oneHour.directional_sample_count ?? "—"}, 95% CI ${oneHour.directional_accuracy_ci95_pct ? `${oneHour.directional_accuracy_ci95_pct[0]}–${oneHour.directional_accuracy_ci95_pct[1]}%` : "—"})`} · score +{scores.positive} / 0:{scores.neutral} / −{scores.negative}</strong></article> })}</div></section>
}
function readinessStatus(readiness: { ready_count: number; pending_count: number; data_gap_count: number }) { if (readiness.data_gap_count > 0) return "data-gap"; if (readiness.pending_count > 0) return "pending"; return "ready" }
function readinessStatusLabel(readiness: { ready_count: number; pending_count: number; data_gap_count: number }) { const status = readinessStatus(readiness); return status === "data-gap" ? "нет данных" : status === "pending" ? "ожидается" : "готово" }
function qualityStatusLabel(status: "insufficient_sample" | "collecting" | "review_candidate") { return status === "insufficient_sample" ? "insufficient sample" : status === "collecting" ? "outcome collection" : "review candidate" }
function ValidationReplaySummary({ report }: { report?: ValidationDepthReport }) { const replay = report?.historical_replay; const horizons = Object.entries(replay?.by_horizon ?? {}); const ready1h = replay?.by_horizon["1h"]?.sample_size ?? 0; const incomplete = horizons.reduce((sum, [, item]) => sum + (item.pending_count ?? 0) + (item.data_gap_count ?? 0), 0); return <section className="room-section validation-replay"><div className="section-title"><h2>Historical replay</h2><span>immutable sample · read-only</span></div><p>{replay?.event_count ?? 0} events · {ready1h} ready 1h · {incomplete} pending/data gaps</p>{horizons.map(([horizon, item]) => { const pending = item.pending_count ?? 0; const gaps = item.data_gap_count ?? 0; return pending || gaps ? <span key={horizon}>{horizon}: {pending ? `${pending} pending` : ""}{pending && gaps ? " · " : ""}{gaps ? `${gaps} data gaps` : ""}</span> : null })}</section> }
function ValidationHorizonSummary({ report }: { report?: ValidationDepthReport }) { const horizons = ["1h", "6h", "1d", "1w"] as const; return <section className="room-section validation-summary"><div className="section-title"><h2>Forward validation</h2><span>replay · horizon quality · read-only</span></div><div className="validation-horizon-grid">{horizons.map(horizon => { const item = report?.by_horizon[horizon]; const status = item?.data_gap_count ? "data_gap" : item?.pending_count ? "pending" : item?.sample_size ? "ready" : "pending"; return <article className="validation-horizon-card" key={horizon}><div><b>{horizon}</b><span className={status}>{forwardValidationStatusLabel(status)}</span></div><strong>{item?.average_return_pct == null || status === "data_gap" ? "нет данных" : formatOutcome(item.average_return_pct)}</strong><small>{item?.sample_size ?? 0} samples · {item?.pending_count ?? 0} pending</small><em>{item?.directional_error_count ?? 0} directional errors · {item?.conflict_count ?? 0} conflicts</em></article> })}</div></section> }
function ValidationCollectionSummary({ report }: { report?: ValidationReport }) { const item = report?.collection?.by_horizon["1h"]; return <section className="room-section validation-replay"><div className="section-title"><h2>Collection pool</h2><span>all persisted events · read-only</span></div><p>{item?.sample_size ?? 0} ready 1h · {item?.pending_count ?? 0} pending · reviewed subset remains separate</p></section> }
function ValidationArchiveSummary({ report }: { report?: ArchiveValidationReport }) { const gate = report?.time_split?.dataset_gate; const train = gate?.train_1h; const test = gate?.test_1h; return <section className="room-section validation-replay"><div className="section-title"><h2>Archive validation</h2><span>isolated candles · read-only</span></div><p>{report?.event_count ?? 0} events · train {train?.status ?? "blocked"} · test {test?.status ?? "blocked"}</p><div className="validation-stats"><Metric label="Train 1h" value={`${train?.sample_size ?? 0}`} detail={`${train?.coverage_pct ?? 0}% coverage`} /><Metric label="Test 1h" value={`${test?.sample_size ?? 0}`} detail={`${test?.coverage_pct ?? 0}% coverage`} /><Metric label="Promotion" value={test?.status === "ready" ? "allowed" : "blocked"} detail="no weight changes" /></div></section> }
function ValidationDimensions({ report, policy }: { report?: ValidationDepthReport; policy?: ValidationPolicyReport }) { const dimensions = Object.entries(report?.by_dimension ?? {}); return <section className="room-section validation-dimensions"><details><summary><span><b>Dimension breakdown</b><small>quality slices · metadata coverage · policy actions</small></span><em>{dimensions.length ? `${dimensions.length} dimensions` : "нет данных"}</em></summary><div className="dimension-grid">{dimensions.map(([dimension, buckets]) => <article className="dimension-card" key={dimension}><div className="dimension-head"><b>{dimension.replaceAll("_", " ")}</b><span>{Object.keys(buckets).length} buckets</span></div>{Object.entries(buckets).map(([bucket, value]) => <div className="dimension-bucket" key={bucket}><div><strong>{bucket === "unknown" ? "нет данных" : bucket}</strong><span>{bucket === "unknown" ? "metadata отсутствует" : "observed"}</span></div><small>{value.count} events · {value.ready_count_1h} ready 1h</small><em>{value.average_return_pct_1h == null ? "return: нет данных" : `return: ${formatOutcome(value.average_return_pct_1h)}`} · {value.directional_accuracy_pct_1h == null ? "accuracy: нет данных" : `accuracy: ${value.directional_accuracy_pct_1h}%`}</em></div>)}</article>)}</div>{policy?.dimension_actions.length ? <div className="dimension-actions"><b>Policy actions</b>{policy.dimension_actions.map((action, index) => <p key={`${action.dimension}-${action.bucket}-${index}`}><strong>{action.dimension} / {action.bucket}</strong> — {action.action}<small>{action.reason}</small></p>)}</div> : null}</details></section> }
function Reviews() { const [status,setStatus]=useState<ReviewStatus>("pending");const q=useQuery({queryKey:["reviews",status],queryFn:()=>getReviews(status),refetchInterval:30000});const summary=useQuery({queryKey:["review-summary"],queryFn:getReviewSummary});const validation=useQuery({queryKey:["validation"],queryFn:getValidationReport});const archive=useQuery({queryKey:["validation-archive"],queryFn:()=>getArchiveValidation(10000,0.8)});const depth=useQuery({queryKey:["validation-depth"],queryFn:getValidationDepth});const policy=useQuery({queryKey:["validation-policy"],queryFn:getValidationPolicy});const mutation=useMutation({mutationFn:({id,status}:{id:string;status:Exclude<ReviewStatus,"pending">})=>updateReview(id,status,"Решение аналитика"),onSuccess:()=>{void q.refetch();}});if(q.isPending)return <Loading/>;if(q.isError)return <Failure/>;const orderedReviews=[...q.data.reviews].sort((a,b)=>reviewPriority(b)-reviewPriority(a));const queue=reviewQueueSummary(orderedReviews);return <Frame eyebrow="VALIDATION LAB / 03" title="Validation" description="Replay, forward outcomes and human review are separate layers. Pending is not a failure."><section className="validation-banner"><div><span className="kicker">Policy readiness</span><strong>{policy.data?.status??"loading"}</strong><p>{policy.data?.recommendation??"Собираем наблюдаемые outcomes."}</p></div><div className="validation-stats"><Metric label="Reviewed" value={String(summary.data?.reviewed_count??"—")} detail="events"/><Metric label="Ready 1h" value={String(summary.data?.ready_count_1h??"—")} detail="outcomes"/><Metric label="Errors" value={String(sumErrors(depth.data))} detail="directional"/></div></section><section className="review-queue-note"><b>Analyst review queue</b><span>Review annotations only · execution disabled · evidence remains immutable</span><div className="queue-counters"><span>{queue.total} pending</span><span>{queue.high} high severity</span><span>{queue.ready} ready for review</span><span>{queue.dataGap} data gap</span></div></section><ValidationCollectionSummary report={validation.data}/><ValidationArchiveSummary report={archive.data}/><ValidationReplaySummary report={depth.data}/><ValidationHorizonSummary report={depth.data}/><ValidationDimensions report={depth.data} policy={policy.data}/><div className="filter-pills" role="tablist">{([["pending","Ожидают"],["confirmed","Подтверждены"],["refuted","Опровергнуты"],["deferred","Отложены"]] as const).map(([value,label])=><button key={value} role="tab" aria-selected={status===value} className={status===value?"active":""} onClick={()=>setStatus(value)}>{label}</button>)}</div><div className="review-feed">{orderedReviews.map(item=><ReviewCard key={item.event_id} item={item} pending={mutation.isPending} onReview={next=>mutation.mutate({id:item.event_id,status:next})}/>)}</div></Frame>}
function ReviewCard({item,pending,onReview}:{item:ReviewItem;pending:boolean;onReview:(status:Exclude<ReviewStatus,"pending">)=>void}){return <article className="review-card"><div className="review-top"><b>{item.asset??"—"}</b><Severity severity={item.severity??"low"}/><span>{item.review.status}</span></div><h2>{item.fact ? factorSummary(item.fact) : "Signal review"}</h2>{item.fact && <details className="factor-details"><summary>Показать factor breakdown</summary><p>{item.fact}</p></details>}<p>{item.market_direction??"нет направления"} · confidence {item.confidence==null?"—":`${Math.round(item.confidence*100)}%`}</p><OutcomeLine outcomes={item.outcomes}/><div className="review-actions"><button disabled={pending} onClick={()=>onReview("confirmed")}>Подтвердить</button><button disabled={pending} onClick={()=>onReview("refuted")}>Опровергнуть</button><button disabled={pending} onClick={()=>onReview("deferred")}>Отложить</button></div></article>}
function OutcomeLine({outcomes}:{outcomes?:Record<"1h"|"6h"|"1d"|"1w",ForwardOutcome>}){if(!outcomes)return null;return <div className="outcome-line">{(["1h","6h","1d","1w"] as const).map(h=>{const outcome=outcomes[h];const label=outcome?.status === "ready" && outcome.return_pct != null ? formatOutcome(outcome.return_pct) : outcome?.status === "data_gap" ? "data gap" : "ожидание forward data";const reason=outcome?.reason ? ` · ${String(outcome.reason).replaceAll("_"," ")}` : "";return <span key={h} className={outcome?.status} title={reason.trim() || undefined}>{h}<b>{label}</b>{reason && <small>{reason}</small>}</span>})}</div>}

function Events(){const q=useQuery({queryKey:["events"],queryFn:()=>getEvents({limit:50})});if(q.isPending)return <Loading/>;if(q.isError)return <Failure/>;return <Frame eyebrow="OBSERVATORY / 04" title="Журнал событий" description="Immutable observation log — от новых к старым, с исходным evidence context."><div className="event-feed">{q.data.events.length?q.data.events.map(e=><EventRow key={e.event_id} event={e}/>):<Empty>Записанных событий пока нет.</Empty>}</div></Frame>}
function EventRow({event}:{event:EventRecord}){return <article className="event-card"><div className="event-time">{formatDate(event.observed_at)}<span>{event.asset}</span></div><div><div className="event-head"><Severity severity={event.severity}/><b>{signalTypeLabel(event.signal_type)}</b></div><p>{event.fact}</p><details><summary>Evidence context</summary><p>{event.basis}</p><span>{event.source_urls.length} sources · confidence {Math.round(event.confidence*100)}%</span></details></div></article>}
function Health(){const q=useQuery({queryKey:["health"],queryFn:getHealth,refetchInterval:30000});if(q.isPending)return <Loading/>;if(q.isError)return <Failure/>;const d=q.data;return <Frame eyebrow="SYSTEM / 05" title="Состояние системы" description="Operational readiness of data collection, persistence and outcome materialization."><div className="health-grid">{[["API",d.status==="ok"?"online":d.status,d.api_version],["Database",d.database.ok?"ready":"unavailable","persistence"],["Provider",d.provider.name,d.provider.last_success_at?formatDate(d.provider.last_success_at):"not refreshed"],["Social",d.social.enabled?"enabled":"on demand",d.social.entrypoint],["Outcome worker",d.outcomes.worker?.status??"not started",d.outcomes.worker?`${d.outcomes.worker.ready} ready · ${d.outcomes.worker.pending} pending`:"awaiting first run"]].map(([label,value,detail])=><article className="health-tile" key={label}><span className="kicker">{label}</span><strong><i className={value==="online"||value==="ready"||value==="enabled"?"good":"neutral"}/>{value}</strong><small>{detail}</small></article>)}</div><div className="safety-note"><b>AUTO_TRADE: FALSE</b><span>Исследовательский режим. Нет signing, wallet access или execution.</span></div></Frame>}
function GitHub(){const q=useQuery({queryKey:["github"],queryFn:()=>getGitHubWatch(100)});const poll=useMutation({mutationFn:pollGitHubWatch,onSuccess:()=>q.refetch()});if(q.isPending)return <Loading/>;if(q.isError)return <Failure/>;const d=q.data;const latest=d.events[0]?.occurred_at;return <Frame eyebrow="EXTERNAL EVIDENCE / 06" title="GitHub Watch" description="Read-only monitoring of public repository activity."><div className="github-banner"><div><span className="kicker">Watch status</span><strong>{d.enabled?"enabled":"not configured"}</strong><p>{d.repos.length} repositories · {d.events.length} observed events{latest ? ` · latest ${formatEvidenceDate(latest)}` : ""}</p></div><button onClick={()=>poll.mutate()} disabled={poll.isPending}>{poll.isPending?"Polling…":"Check now"}</button></div><div className="event-feed">{d.events.length?d.events.slice(0,20).map(e=><article className="github-event" key={e.external_id}><div><b>{e.repo}</b><span>{e.kind}</span></div><p>{e.title}</p><time dateTime={e.occurred_at} title={e.occurred_at}>{formatEvidenceDate(e.occurred_at)}</time></article>):<Empty>GitHub events not collected.</Empty>}</div></Frame>}
function Metric({label,value,detail}:{label:string;value:string;detail:string}){return <div className="metric"><span>{label}</span><strong>{value}</strong><small>{detail}</small></div>}
function Fact({label,value}:{label:string;value:string}){return <div className="fact"><span>{label}</span><strong>{value}</strong></div>}
function Severity({severity}:{severity:"low"|"medium"|"high"}){return <span className={`severity severity-${severity}`}>{severityLabel(severity)}</span>}
function severityRank(v:string){return ({low:1,medium:2,high:3} as Record<string,number>)[v]??0}
function severityLabel(v:string){return ({low:"низкий",medium:"средний",high:"высокий"} as Record<string,string>)[v]??v}
function signalTypeLabel(v:string){return ({composite_market_risk:"сводный рыночный риск",funding_rate:"ставка финансирования",mark_mid_spread:"спред mark/mid",open_interest_turnover:"оборот OI",mark_price_change:"изменение цены"} as Record<string,string>)[v]??v.replaceAll("_"," ")}
function safeHost(v:string){try{return new URL(v).hostname}catch{return v}}
function formatPrice(v:number){return new Intl.NumberFormat("ru-RU",{style:"currency",currency:"USD",maximumFractionDigits:v>=100?2:4}).format(v)}
function formatPercent(v:number){return `${new Intl.NumberFormat("ru-RU",{maximumFractionDigits:3}).format(v)}%`}
function formatCompact(v:number){return new Intl.NumberFormat("ru-RU",{notation:"compact",maximumFractionDigits:2}).format(v)}
function candleIntervalMs(timeframe: string){ return ({"1m":60_000,"10m":600_000,"1h":3_600_000,"6h":21_600_000,"1d":86_400_000,"1w":604_800_000} as Record<string,number>)[timeframe] ?? 0 }
export function candleFreshnessStatus(candleOpenTime: number, timeframe: string, nowMs = Date.now()){ const interval = candleIntervalMs(timeframe); return interval > 0 && nowMs > candleOpenTime + 2 * interval ? "stale" : "awaiting_close" }
export function indicatorSnapshotAgeLabel(snapshotTime: number, nowMs = Date.now()){ const minutes = Math.max(0, Math.floor((nowMs - snapshotTime) / 60_000)); if (minutes < 60) return `${minutes}м`; const hours = Math.floor(minutes / 60); if (hours < 48) return `${hours}ч`; return `${Math.floor(hours / 24)}д` }
export function indicatorSnapshotStatus(snapshotTime: number, nowMs = Date.now()){ return nowMs - snapshotTime > 3 * 60_000 ? "stale" : "fresh" }
export function candleClosedAgeLabel(candleOpenTime: number, timeframe: string, nowMs = Date.now()){ const closedAt = candleOpenTime + candleIntervalMs(timeframe); const minutes = Math.max(0, Math.floor((nowMs - closedAt) / 60_000)); if (minutes < 60) return `${minutes}м`; const hours = Math.floor(minutes / 60); if (hours < 48) return `${hours}ч`; return `${Math.floor(hours / 24)}д` }
function candleFreshnessStatusLabel(status: ReturnType<typeof candleFreshnessStatus>){ return status === "stale" ? "данные устарели" : "ожидается закрытие текущего бара" }
export function CandleFreshness({ candleOpenTime, timeframe }: { candleOpenTime: number; timeframe: string }) { const [now, setNow] = useState(() => Date.now()); useEffect(() => { const timer = window.setInterval(() => setNow(Date.now()), 60_000); return () => window.clearInterval(timer) }, []); return <><span aria-label="Свежесть баров">Свежесть баров <b>{candleFreshnessStatusLabel(candleFreshnessStatus(candleOpenTime, timeframe, now))}</b></span><span aria-label="Возраст последнего закрытого бара">Возраст последнего закрытого бара <b>{candleClosedAgeLabel(candleOpenTime, timeframe, now)}</b></span></> }
function formatCandleOpenTime(v: number){ return new Intl.DateTimeFormat("ru-RU",{dateStyle:"medium",timeStyle:"short"}).format(new Date(v)) }
function formatEvidenceDate(v: string){ const date = new Date(v); if (Number.isNaN(date.getTime())) return "нет даты"; const diff = Date.now() - date.getTime(); const hours = Math.floor(Math.max(0, diff) / 3600000); const exact = new Intl.DateTimeFormat("ru-RU",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"}).format(date); const age = hours < 1 ? "сейчас" : hours < 24 ? `${hours} ч назад` : hours < 168 ? `${Math.floor(hours / 24)} дн назад` : `${Math.floor(hours / 168)} нед назад`; return `${exact} · ${age}` }
function formatDate(v: string | number){ const date = typeof v === "number" ? new Date(v * 1000) : new Date(v); return new Intl.DateTimeFormat("ru-RU",{dateStyle:"medium",timeStyle:"short"}).format(date) }
function formatOutcome(v:number){return `${v>=0?"+":""}${v.toFixed(2)}%`}
function sumErrors(report?: ValidationDepthReport) { return report?.by_horizon ? Object.values(report.by_horizon).reduce((sum, row) => sum + row.directional_error_count, 0) : "—" }
export function driverCountLabel(value:number){const a=value%10,b=value%100;return a===1&&b!==11?"драйвер":a>=2&&a<=4&&(b<10||b>=20)?"драйвера":"драйверов"}
export function newsCountLabel(value:number){const a=value%10,b=value%100;return a===1&&b!==11?"запись":a>=2&&a<=4&&(b<10||b>=20)?"записи":"записей"}
export function forwardValidationStatus(s:Array<"pending"|"ready"|"data_gap">){return s.includes("data_gap")?"data_gap":s.includes("pending")?"pending":"ready"}
export function forwardValidationStatusLabel(s:"pending"|"ready"|"data_gap"){return s==="data_gap"?"data gap":s==="pending"?"ожидание forward data":"результат доступен"}
export function reviewPriority(item: Pick<ReviewItem, "severity"> & { outcomes?: Partial<Record<"1h"|"6h"|"1d"|"1w", ForwardOutcome>> }){const severity=severityRank(item.severity??"low")*100;const ready=Object.values(item.outcomes ?? {}).some(outcome=>outcome.status === "ready") ? 10 : 0;const gap=Object.values(item.outcomes ?? {}).some(outcome=>outcome.status === "data_gap") ? 5 : 0;return severity+ready+gap}
export function reviewQueueSummary(items: Array<Pick<ReviewItem, "severity"> & { outcomes?: Partial<Record<"1h"|"6h"|"1d"|"1w", ForwardOutcome>> }>){return {total:items.length,high:items.filter(item=>item.severity==="high").length,ready:items.filter(item=>Object.values(item.outcomes ?? {}).some(outcome=>outcome.status === "ready")).length,dataGap:items.filter(item=>Object.values(item.outcomes ?? {}).some(outcome=>outcome.status === "data_gap")).length}}
export function factorSummary(fact:string){const factors=(fact.match(/[a-z_]+=(?:high|medium|low)/g) ?? []);const elevated=factors.filter(f=>f.endsWith("=high")||f.endsWith("=medium")).length;return `${factors.length || 0} факторов${elevated ? ` · ${elevated} повышенный риск` : ""}`}
export function scoreDistribution(scores:number[]){return scores.reduce((d,s)=>{if(s>0)d.positive++;else if(s<0)d.negative++;else d.neutral++;return d},{positive:0,neutral:0,negative:0})}
